import{_ as o,o as d,c,a3 as t}from"./chunks/framework.DX8Ye6Dg.js";const g=JSON.parse('{"title":"How to use the TUI","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/use-the-tui.md","filePath":"how-to/use-the-tui.md"}'),s={name:"how-to/use-the-tui.md"};function a(r,e,i,n,l,h){return d(),c("div",null,[...e[0]||(e[0]=[t('<h1 id="how-to-use-the-tui" tabindex="-1">How to use the TUI <a class="header-anchor" href="#how-to-use-the-tui" aria-label="Permalink to &quot;How to use the TUI&quot;">​</a></h1><p><code>tamias ui</code> opens an interactive console — the same operations as the CLI verbs, without memorizing flags. It needs the <code>tui</code> cargo feature (on by default; <code>cargo install tamias --no-default-features</code> builds the lean binary without it).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui</span></span></code></pre></div><h2 id="panes" tabindex="-1">Panes <a class="header-anchor" href="#panes" aria-label="Permalink to &quot;Panes&quot;">​</a></h2><p>Six panes, tab-ordered for browsing first and search last — <code>Tab</code>/<code>l</code> and <code>h</code>/<code>Shift-Tab</code> cycle, <code>1</code>–<code>6</code> jump directly (<code>1</code> Home … <code>6</code> Registry). <code>Esc</code>/<code>q</code> closes an open package page before it quits; pane switches close the page too.</p><ul><li><strong>Home</strong> — the landing pane: wordmark, stats strip, and a recently-installed list. <code>j</code>/<code>k</code> + <code>g</code>/<code>G</code> walk the recents, <code>Enter</code> opens a package page, <code>/</code> jumps to registry search, <code>i</code> installs by ref.</li><li><strong>Installed</strong> — store entries collapsed to the latest version per package (<code>· N versions</code> counts the other copies the store keeps). <code>Enter</code> opens the package page; <code>/</code> filters client-side, <code>F</code> clears. <code>v</code> verify, <code>u</code>/<code>U</code> update one/all, <code>p</code> pin → new ref, <code>x</code> remove (confirm — on a multi-version group it opens a picker where space/<code>a</code>/<code>n</code>/<code>/</code> narrow the set and <code>⏎</code> removes it), <code>c</code>/<code>C</code> cache clean (&gt;30d / all), <code>d</code> doctor, <code>i</code> install by ref, <code>R</code> reload.</li><li><strong>Registry</strong> — search-as-you-type against a registry (debounced; <code>Enter</code> fires immediately). Substring over name/scope/description/ keywords ranks first, then fuzzy name-subsequence hits. Results mark <code>[signed]</code>, <code>installed &lt;ver&gt;</code>, and version counts. <code>Enter</code> opens the package page, <code>i</code> installs the result, <code>:registry &lt;name&gt;</code> picks the target (a configured name or a raw dir/http ref; bare <code>:registry</code> resets to default routing).</li><li><strong>Services</strong> — provider services with unit state, one row per unit (<code>×N</code> counts the store entries providing it). <code>s</code>/<code>S</code> start/stop, <code>!</code> restart, <code>e</code>/<code>E</code> enable/disable, <code>d</code> deploy, <code>x</code> uninstall (all confirmed), <code>t</code>/<code>T</code> tail/follow the journal, <code>n</code> runs the service in the foreground (<code>x</code> kills a live stream), <code>Enter</code> opens the newest provider&#39;s package page, <code>R</code> refreshes.</li><li><strong>Project</strong> — the project manifest&#39;s <code>deps:</code> as an editable table: <code>a</code> add a ref, <code>d</code>/<code>x</code> remove, <code>e</code> edit (installs the new ref, then swaps — a failed install leaves the manifest untouched). Writes go through the same manifest+lock path as <code>tamias add</code>. <code>s</code> (or <code>:sync</code>) reconciles <code>deps:</code> against the store + lock — <code>tamias sync</code>&#39;s pass, behind a confirm; <code>S</code> (or <code>:sync --from-lock</code>) installs <code>tamias.lock</code> verbatim. <code>R</code> reloads the manifest.</li><li><strong>Publish</strong> — <code>p</code> packs a payload dir (<code>bundle pack</code>), <code>P</code> publishes (dir + registry prompts, confirmed), <code>r</code> lists configured registries (a table you can select from), <code>R</code> reloads the registry list.</li></ul><h2 id="package-pages" tabindex="-1">Package pages <a class="header-anchor" href="#package-pages" aria-label="Permalink to &quot;Package pages&quot;">​</a></h2><p><code>Enter</code> on an Installed row, a Registry result, a Home recent, or a Services provider opens an npm-style package page: header chips, description, install command, deps/services/meta, the installed versions list, provenance last. <code>j</code>/<code>k</code> scroll, <code>g</code>/<code>G</code> jump to the ends, the wheel scrolls, <code>y</code> copies the install ref. <code>v</code> focuses the versions section — <code>j</code>/<code>k</code>/<code>g</code>/<code>G</code> pick one and <code>i</code> installs that exact version (registry siblings or installed store copies — rollback is an exact-version install, not an activate). Superseded copies are dropped with <code>:prune</code>. <code>esc</code>/<code>q</code>/<code>h</code>/<code>←</code> closes the page and returns to where <code>Enter</code> was pressed.</p><h2 id="keys" tabindex="-1">Keys <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;Keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>j</code>/<code>k</code>, arrows, wheel</td><td>move / scroll</td></tr><tr><td><code>g</code>/<code>G</code></td><td>top / bottom</td></tr><tr><td><code>Enter</code></td><td>package page</td></tr><tr><td><code>/</code></td><td>filter (Installed) / search (Registry) / jump to registry search (Home)</td></tr><tr><td><code>F</code></td><td>clear filter</td></tr><tr><td><code>Tab</code>/<code>l</code>, <code>h</code>/<code>Shift-Tab</code>, <code>1</code>–<code>6</code></td><td>next / prev / jump pane</td></tr><tr><td><code>:</code></td><td>command line — <code>Tab</code> completes, <code>↑</code>/<code>↓</code> history, line editing (arrows, <code>Home</code>/<code>End</code>, <code>Ctrl-A</code>/<code>E</code>/<code>U</code>/<code>W</code>)</td></tr><tr><td><code>L</code> or <code>:log</code></td><td>op-log sidebar — <code>j</code>/<code>k</code> scroll, <code>g</code>/<code>G</code> ends, <code>q</code> close</td></tr><tr><td><code>?</code></td><td>help overlay (scrollable; <code>j</code>/<code>k</code>, <code>PgUp</code>/<code>PgDn</code>, <code>g</code>/<code>G</code>, wheel; <code>esc</code>/<code>?</code>/<code>q</code> close)</td></tr><tr><td><code>R</code></td><td>reload</td></tr><tr><td><code>q</code> / <code>Ctrl-C</code></td><td>quit (closes an open page first; <code>C-c</code> quits anywhere)</td></tr></tbody></table><p>Pane-gated verbs: Installed <code>v u U p x c C d i</code>, Services <code>s S ! e E d x t T n R</code>, Project <code>a d x e s S R</code>, Publish <code>p P r R</code>, Registry <code>i</code> (+ <code>v</code> on a detail page). Dead keys flash a hint in the status bar.</p><p>The <code>:</code> command line accepts: <code>:q</code> <code>:r</code>/<code>:reload</code> <code>:help</code> <code>:log</code><code>:install &lt;ref&gt;</code> <code>:remove &lt;name&gt;</code> <code>:uninstall &lt;name&gt;</code> (provider teardown) <code>:verify &lt;name&gt;</code> <code>:update [name] [--no-prune]</code><code>:pin &lt;name&gt; &lt;ref&gt;</code> <code>:search &lt;q&gt;</code> <code>:registry &lt;name&gt;</code> <code>:clean [all]</code><code>:doctor</code> <code>:services</code> <code>:service &lt;verb&gt; &lt;unit&gt;</code> <code>:run &lt;pkg&gt; [svc]</code><code>:logs &lt;pkg|unit&gt; [-f]</code> <code>:deploy &lt;name&gt;</code> <code>:manifest</code> <code>:pack &lt;dir&gt; [out]</code> <code>:publish &lt;dir&gt; [registry]</code> <code>:registries</code> <code>:sync [--from-lock]</code><code>:prune [--keep N]</code>.</p><p>Mouse: the wheel scrolls (the package page when open), a click selects a row, a click on a tab switches panes.</p><p>Mutating verbs ask <code>y</code>/<code>n</code> first (default <code>n</code>). Installs that ship bundled <code>drivers/</code> raise the consent prompt — answering <code>y</code> is the equivalent of <code>--allow-drivers</code>; there is no env-var shortcut in the TUI.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p><code>tamias ui</code> opens on the <strong>Home</strong> pane — wordmark, stats, and recently-installed rows. <code>Tab</code> reaches <strong>Installed</strong>; <code>?</code> shows the scrollable key overlay; <code>q</code> quits.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Long ops (install, publish, verify) run on a worker thread; phases stream into the right-side op log (<code>L</code>/<code>:log</code>) with a spinner in the status bar.</li><li>The TUI watches the store root and reloads when it changes on disk — installs from other terminals show up without <code>R</code> (a slow rescan covers missed events).</li><li>Everything the TUI does is also available as CLI verbs or <code>tamias serve</code> ops — the TUI is a front-end, not a second engine.</li></ul>',18)])])}const u=o(s,[["render",a]]);export{g as __pageData,u as default};
